const source = $input.first().json;
const data = source.contactsData || {};
const token = String(source.tokenText || '').trim();
const timezone = 'America/Bogota';

const weekdayMap = {
  monday: 'lunes',
  tuesday: 'martes',
  wednesday: 'miércoles',
  thursday: 'jueves',
  friday: 'viernes',
  saturday: 'sábado',
  sunday: 'domingo',
};

const aliases = {
  miercoles: 'miércoles',
  sabado: 'sábado',
};

function normalizeDay(value) {
  const lowered = String(value || '').trim().toLowerCase();
  return aliases[lowered] || lowered;
}

function normalizePhone(rawPhone) {
  let digits = String(rawPhone || '').replace(/\D/g, '');
  digits = digits.replace(/^0+/, '');
  if (digits.length === 10 && digits.startsWith('3')) {
    digits = `57${digits}`;
  }
  if (digits.length === 12 && digits.startsWith('57') && digits[2] === '3') {
    return digits;
  }
  return digits || null;
}

function weekBucket(dayOfMonth) {
  if (dayOfMonth >= 1 && dayOfMonth <= 8) return 1;
  if (dayOfMonth >= 9 && dayOfMonth <= 16) return 2;
  if (dayOfMonth >= 17 && dayOfMonth <= 24) return 3;
  return 4;
}

function nowInTimezone(tz) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    weekday: 'long',
  }).formatToParts(new Date());
  const byType = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return {
    isoLocal: `${byType.year}-${byType.month}-${byType.day}T${byType.hour}:${byType.minute}:${byType.second}`,
    weekday: weekdayMap[(byType.weekday || '').toLowerCase()] || byType.weekday,
    dayOfMonth: Number(byType.day),
  };
}

function composeMessage(baseMessage, promotion) {
  const cleanBase = String(baseMessage || '').trim();
  const cleanPromotion = String(promotion || '').trim();
  if (!cleanPromotion) return cleanBase;
  if (!cleanBase) return cleanPromotion;
  return `${cleanBase}\n\n${cleanPromotion}`;
}

const now = nowInTimezone(timezone);
const selectedDay = normalizeDay(now.weekday);
const selectedWeekBucket = weekBucket(now.dayOfMonth);
const promociones = data.promociones_por_semana || {};
const promotion = promociones[String(selectedWeekBucket)] || promociones[selectedWeekBucket] || '';
const contacts = Array.isArray(data.mensajes_por_dia?.[selectedDay]) ? data.mensajes_por_dia[selectedDay] : [];

if (!token) {
  return [{ json: { should_send: false, status: 'missing_token', system_day: now.weekday, selected_day: selectedDay, contact_count: contacts.length, generated_at: now.isoLocal } }];
}

const sanitizedContacts = contacts
  .filter((item) => Array.isArray(item) && item.length >= 2)
  .map((item) => ({
    number: normalizePhone(item[0]),
    text: composeMessage(item[1], promotion),
  }))
  .filter((item) => item.number && item.text);

if (!sanitizedContacts.length) {
  return [{ json: { should_send: false, status: 'no_contacts_for_today', system_day: now.weekday, selected_day: selectedDay, day_matches_system: selectedDay === now.weekday, selected_week_bucket: selectedWeekBucket, promotion, contact_count: 0, generated_at: now.isoLocal } }];
}

return sanitizedContacts.map((contact, index) => ({
  json: {
    should_send: true,
    status: 'ready_to_send',
    generated_at: now.isoLocal,
    system_day: now.weekday,
    selected_day: selectedDay,
    day_matches_system: selectedDay === now.weekday,
    selected_week_bucket: selectedWeekBucket,
    promotion,
    contact_count: sanitizedContacts.length,
    contact_index: index + 1,
    number: contact.number,
    text: contact.text,
    evolution_api_key: token,
  }
}));
